const items = [];
const allInputs = $input.all();

for (const inputItem of allInputs) {
  const xmlText = inputItem?.json?.data || "";
  if (!xmlText) continue;

  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;

  while ((match = itemRegex.exec(xmlText)) !== null) {
    const itemContent = match[1];

    const getTagValue = (tag) => {
      const regex = new RegExp(
        `<${tag}>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([^<]*))`,
        "i"
      );
      const tagMatch = itemContent.match(regex);
      return ((tagMatch && (tagMatch[1] || tagMatch[2])) || "").trim();
    };

    const title = getTagValue("title");
    const link = getTagValue("link");
    const description = getTagValue("description");
    const pubDate = getTagValue("pubDate").replace(/[\n\r\t]/g, " ").replace(/\s+/g, " ").trim();

    if (!title || !link) continue;

    items.push({
      json: {
        title,
        url: link,
        description: description.replace(/<[^>]*>/g, "").trim(),
        publishedDate: pubDate,
      },
    });
  }
}

console.log("Total items parsed from all sources:", items.length);
return items;

// Embedding du nouvel article (depuis Edit Fields)
const newEmbedding = $("Edit Fields").item.json.embedding;

// Tous les articles existants avec embeddings (depuis MongoDB Find All)
const existingArticles = $input.all();

// Fonction pour normaliser un vecteur (le transformer en vecteur unitaire)
function normalize(vec) {
  const norm = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0));
  if (norm === 0) return vec; // évite division par zéro
  return vec.map(v => v / norm);
}

// Fonction dot product (produit scalaire)
function dotProduct(a, b) {
  let sum = 0;
  for (let i = 0; i < a.length; i++) {
    sum += a[i] * b[i];
  }
  return sum;
}

// Normaliser le nouvel embedding UNE SEULE FOIS
const normalizedNewEmbedding = normalize(newEmbedding);

// Calculer similarité max avec tous les embeddings existants
let maxSimilarity = 0;
let closestArticle = null;

for (const article of existingArticles) {
  if (article.json.embedding && article.json.embedding.length > 0) {
    // Normaliser l'embedding existant, puis dot product = cosine similarity
    const normalizedExisting = normalize(article.json.embedding);
    const sim = dotProduct(normalizedNewEmbedding, normalizedExisting);

    if (sim > maxSimilarity) {
      maxSimilarity = sim;
      closestArticle = article.json.title || null;
    }
  }
}

// Novelty score = inverse de la similarité max
const noveltyScore = parseFloat((1 - maxSimilarity).toFixed(4));

// Classifier la nouveauté
let noveltyLevel;
if (noveltyScore > 0.7) {
  noveltyLevel = "HIGH";
} else if (noveltyScore > 0.4) {
  noveltyLevel = "MEDIUM";
} else {
  noveltyLevel = "LOW";
}

return [{
  json: {
    // Données de l'article
    title: $("Edit Fields").item.json.title,
    url: $("Edit Fields").item.json.url,
    description: $("Edit Fields").item.json.description,
    publishedDate: $("Edit Fields").item.json.publishedDate,
    category: $("Edit Fields").item.json.category,
    embedding: newEmbedding,
    // Résultats cosinus (via dot product pré-normalisé)
    novelty_score: noveltyScore,
    novelty_level: noveltyLevel,
    max_similarity: parseFloat(maxSimilarity.toFixed(4)),
    closest_article: closestArticle
  }
}];

// Parser la sortie de l'AI Agent
let aiResult;
try {
  aiResult = JSON.parse($json.output.trim());
} catch(e) {
  aiResult = {
    is_potential_trend: false,
    triggers_found: [],
    confidence: 0,
    reason: "parsing error"
  };
}

// Toutes les données viennent de Code (cosinus) qui contient déjà tout
const noveltyData = $('Code').item.json;

return [{
  json: {
    title: noveltyData.title,
    url: noveltyData.url,
    description: noveltyData.description,
    publishedDate: noveltyData.publishedDate,
    category: noveltyData.category,
    embedding: noveltyData.embedding,
    novelty_score: noveltyData.novelty_score,
    novelty_level: noveltyData.novelty_level,
    max_similarity: noveltyData.max_similarity,
    closest_article: noveltyData.closest_article,
    is_potential_trend: aiResult.is_potential_trend,
    triggers_found: aiResult.triggers_found,
    confidence: aiResult.confidence,
    reason: aiResult.reason,
    prediction_made_at: new Date().toISOString(),
    confirmed_trend: false,
    confirmed_at: null
  }
}];
